import * as RT from './runtime.js';
import * as T from './taxes.js';
import * as C from './cinema.js';
import * as H from './finance-history.js';
import {GENRE,GENRES,SCALE,ROLE_NAMES,EVENTS} from './data.js';

/** Feature views use the same game state and mutation path as the base application. */
export function createStudioFeatures(ctx) {
 const {ui,E,X,R,esc,btn,icon,tags,avatar,dialogFrame,pageHead,open,render,renderDialog,mutate,go,persist,toast,relationBadge,timelinePanel,filmCareerNotes,posterPicker}=ctx;
 const state=()=>ctx.getGame(),person=id=>E.person(state(),id);
 let chartData=null;
 function film(id){return state().films.find(f=>f.id===id);}
 function backButton(){return btn(`${icon('back')} 뒤로가기`,'feature-back','','ghost');}
 function deepOpen(type,id,extra={}) {
   // Keep the destination/tabs only. Chart coordinates are regenerated on render.
   ui.peekStack??=[];
   ui.peekStack.push({modal:ui.modal?{...ui.modal}:null,filmTab:ui.filmTab,businessTab:ui.businessTab,reviewPage:ui.reviewPage,ledgerPage:ui.ledgerPage,comparisonQuery:ui.comparisonQuery,comparisonTarget:ui.comparisonTarget});
   ui.reviewPage=0;open(type,id);Object.assign(ui.modal,extra);renderDialog();
 }
 function back(){const previous=ui.peekStack?.pop();if(previous){ui.modal=previous.modal;ui.filmTab=previous.filmTab;ui.businessTab=previous.businessTab;ui.reviewPage=previous.reviewPage;ui.ledgerPage=previous.ledgerPage;chartData=null;ui.comparisonQuery=previous.comparisonQuery??'';ui.comparisonTarget=previous.comparisonTarget??null;renderDialog();}else{ui.modal=null;renderDialog();}}
 function personChip(id,label){const p=person(id);if(!p)return '';return `<button class="person-chip" data-action="person-peek" data-id="${esc(id)}">${avatar(p)}<span><small>${esc(label??ROLE_NAMES[p.role])}</small><strong>${esc(p.name)}</strong></span>${icon('chevron')}</button>`;}
 function companyChip(c){return `<button class="person-chip company-chip" data-action="company-info" data-id="${c.id}"><span class="company-symbol">${X.LOGOS[c.logo??0]}</span><span><small>제작사</small><strong>${esc(c.name)}</strong></span>${icon('chevron')}</button>`;}
 function scoreButton(f,kind,compact=false) {
   const critic=kind==='critic',value=critic?(f.reviews.length?E.reviewScore(state(),f):null):C.viewerScore(f);
   const label=critic?'평론가':f.status==='streaming'?'시청자':'관객';
   return `<button class="rating-button ${critic?'critics':'viewers'} ${compact?'compact':''}" data-action="${critic?'critic-reviews':'audience-reviews'}" data-id="${f.id}" ${value==null?'disabled':''} aria-label="${esc(f.title)} ${label} ${value==null?'집계 전':value+'점 상세평 보기'}"><span>${label}</span><strong>${value??'—'}${value!=null?'<small>/100</small>':''}</strong>${value!=null?icon('chevron'):'<small>집계 전</small>'}</button>`;
 }
 function trendButton(f,r,key,label) {
   const t=H.trendAt(f,r,key),v=key==='audience'?E.viewers(r[key])+'명':E.money(r[key]);
   return `<button class="metric-trend" data-action="film-chart" data-id="${f.id}" data-key="${key}" aria-label="${esc(f.title)} ${label} ${v}, ${t.label}, 그래프 보기"><small>${label}</small><strong>${v}</strong><span class="trend ${t.direction}" title="${esc(t.label)}">${t.symbol} ${t.direction==='new'?'첫 집계':t.label} ${icon('chart')}</span></button>`;
 }
 function boxofficeTable(period) {
   const getRun=f=>!period?null:Number.isInteger(period.week)?f.runs.find(r=>r.week===period.week):f.runs.find(r=>r.month===period.month&&!Number.isInteger(r.week));
   const all=state().films.filter(f=>f.distribution!=='ott'&&getRun(f)).sort((a,b)=>getRun(b).gross-getRun(a).gross);
   if(!all.length)return `<div class="card empty">${icon('chart')}<h3>아직 집계된 흥행 성적이 없습니다.</h3><p>극장 개봉 후 1주를 진행하면 관객·매출·관객평이 집계됩니다.</p></div>`;
   const size=innerWidth<620?2:innerHeight<600?3:6,pages=Math.ceil(all.length/size),page=E.clamp(ui.boxPage??0,0,pages-1);ui.boxPage=page;
   return `<div class="boxoffice-list v12-boxoffice">${all.slice(page*size,(page+1)*size).map((f,i)=>{const r=getRun(f),total=H.runTotalsThrough(f,r),c=state().companies.find(c=>c.id===f.company);return `<article class="boxoffice-row v12-box-row ${f.company==='c0'?'own':''}"><span class="rank ${page*size+i<3?'top':''}">${String(page*size+i+1).padStart(2,'0')}</span><button class="poster-link" data-action="film" data-id="${f.id}" aria-label="${esc(f.title)} 상세">${posterArt(f,f.poster??GENRES.findIndex(g=>g.id===f.genres[0])%12)}</button><div class="boxoffice-title"><button class="film-link" data-action="film" data-id="${f.id}">${esc(f.title)}</button><button class="company-text" data-action="company-info" data-id="${c.id}">${esc(c.name)}${f.company==='c0'?' · MY':''}</button><div class="rating-pair">${scoreButton(f,'critic',true)}${scoreButton(f,'audience',true)}</div></div><div class="boxoffice-cumulative"><small>누적 관객</small><button data-action="film-chart" data-id="${f.id}" data-key="cumulative"><strong>${E.viewers(total.audience)}<small>명</small></strong>${icon('chart')}</button><small>누적 정산 ${E.money(total.receipts)}</small></div><div class="weekly-metrics">${trendButton(f,r,'audience',Number.isInteger(period.week)?'주간 관객':'월간 관객')}${trendButton(f,r,'gross',Number.isInteger(period.week)?'주간 매출':'월간 매출')}</div></article>`;}).join('')}</div>${pages>1?pageControls('box-page',page,pages,`${all.length}편`):''}<p class="small muted rating-note">누적 실적은 표시된 집계 시점까지의 기록입니다. 평점은 게임 내 가상 평가(100점 만점)입니다. 점수를 누르면 상세평, 화살표를 누르면 기록 그래프를 봅니다.</p>`;
 }
 function pageControls(action,page,pages,extra='') {return `<div class="pagination">${btn('이전',action,`data-delta="-1" ${page===0?'disabled':''}`,'ghost small-btn')}<span>${page+1} / ${pages}${extra?' · '+extra:''}</span>${btn('다음',action,`data-delta="1" ${page+1>=pages?'disabled':''}`,'ghost small-btn')}</div>`;}
 function reviewsDialog(f,kind) {
   if(!f)return dialogFrame('평가 기록','','작품이 없습니다.',backButton());
   const isCritic=kind==='critic',all=isCritic?f.reviews:(f.viewerReviews??[]),name=isCritic?'평론가':f.status==='streaming'?'시청자':'관객';
   const score=isCritic?E.reviewScore(state(),f):C.viewerScore(f),size=isCritic?4:6,pages=Math.max(1,Math.ceil(all.length/size)),page=E.clamp(ui.reviewPage??0,0,pages-1);ui.reviewPage=page;
   return dialogFrame(`${name} 상세평`,esc(f.title),`<div class="review-heading"><span>${name} 종합평</span><strong>${score??'—'}<small>/100</small></strong><p>${all.length}개의 가상 평가 ${isCritic?'· 서사·연출·연기·영상·리듬·주제·장르 관점':'· 개인 취향에 따른 다양한 반응'}</p></div>${f.reviewModel==='legacy'&&isCritic?'<div class="notice small">이전 버전에서 이미 개봉한 작품입니다. 당시 평점 기록을 보존하고 상세평을 보완했습니다.</div>':''}<p class="small muted">실제 평론가나 이용자의 평이 아닌 게임 안에서 생성한 감상입니다. ${isCritic?'관객 수가 많다고 평론 점수가 함께 오르지는 않습니다.':'평론과 별도로 이야기의 몰입도·장르 취향·배우 호흡을 평가합니다.'}</p>${all.length?`<div class="review-list">${all.slice(page*size,(page+1)*size).map((r,i)=>`<article class="review-card"><header><div class="reviewer-identity"><strong class="reviewer-name">${esc(r.name)}</strong><small>${esc(r.focus??'관람 후 감상')}</small></div><b>${r.base??r.score}<small>점</small></b></header><p>${esc(r.text??C.criticText(f,r,page*size+i))}</p></article>`).join('')}</div>${pageControls('review-page',page,pages)}`:`<div class="empty"><h3>아직 ${name}평이 없습니다.</h3><p>${isCritic?'제작을 완료하면 평론이 도착합니다.':'극장 개봉 또는 OTT 공개 후 1주를 진행해 주세요.'}</p></div>`}`,backButton());
 }
 function metricValue(n,unit){return unit==='명'?E.viewers(n)+'명':E.money(n);}
 function chart(series,title,unit) {
   if(!series.length){chartData=null;return '<div class="empty"><h3>저장된 기록이 없습니다.</h3><p>기록이 쌓인 시점부터 그래프를 표시합니다. 없는 과거 수치는 생성하지 않습니다.</p></div>';}
   chartData={series,title,unit};const w=680,h=292,left=70,right=20,top=20,bottom=48;
   const numbers=series.map(r=>r.value),low=Math.min(0,...numbers),high=Math.max(0,...numbers),span=Math.max(1,high-low),min=low<0?low-span*.06:0,max=high+span*.08;
   const x=i=>series.length===1?(w+left-right)/2:left+i*(w-left-right)/(series.length-1),y=v=>top+(max-v)*(h-top-bottom)/(max-min);
   chartData.x=x;chartData.y=y;
   const grid=Array.from({length:5},(_,i)=>{const n=min+(max-min)*i/4,py=y(n);return `<g><line x1="${left}" x2="${w-right}" y1="${py}" y2="${py}"/><text x="${left-9}" y="${py+4}" text-anchor="end">${esc(unit==='명'?E.viewers(Math.round(n)):E.round(n).toLocaleString('ko-KR'))}</text></g>`;}).join('');
   const points=series.map((r,i)=>`${x(i).toFixed(2)},${y(r.value).toFixed(2)}`).join(' '),latest=series.at(-1);
   const labelIndices=[...new Set([0,Math.floor((series.length-1)/2),series.length-1])];
   const labels=labelIndices.map(i=>`<text class="chart-date" x="${x(i)}" y="${h-18}" text-anchor="${i===0?'start':i===series.length-1?'end':'middle'}">${esc(series[i].date.replace('년 ','/').replace('월 ','/').replace('주',''))}</text>`).join('');
   return `<div class="history-graph"><div class="chart-summary"><div><small>첫 기록</small><strong>${metricValue(series[0].value,unit)}</strong></div><div><small>최근 기록</small><strong>${metricValue(latest.value,unit)}</strong></div><div><small>기록 수</small><strong>${series.length}건</strong></div></div><svg class="history-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)} 기록 그래프, ${series[0].date}부터 ${latest.date}까지" data-feature-chart="true"><title>${esc(title)} · 단위 ${unit==='명'?'명':'억 원'}</title><g class="chart-grid">${grid}</g><line class="chart-zero" x1="${left}" x2="${w-right}" y1="${y(0)}" y2="${y(0)}"/><polyline class="chart-line" points="${points}"/>${series.length<=60?series.map((r,i)=>`<circle class="chart-dot" cx="${x(i)}" cy="${y(r.value)}" r="3"><title>${esc(r.date)} · ${metricValue(r.value,unit)}</title></circle>`).join(''):''}<circle id="chart-active-dot" class="chart-active-dot" cx="${x(series.length-1)}" cy="${y(latest.value)}" r="6"/>${labels}</svg><label class="chart-slider-label" for="history-point">기록을 짚어 보기 <small>드래그 또는 방향키로 이동</small></label><input id="history-point" class="history-slider" type="range" min="0" max="${Math.max(0,series.length-1)}" value="${series.length-1}" step="1" data-field="chart-point" aria-label="그래프 기록 선택" ${series.length===1?'disabled':''}><p id="chart-readout" class="chart-readout" role="status">${esc(latest.date)} · <strong>${metricValue(latest.value,unit)}</strong>${latest.label?' · '+esc(latest.label):''}</p></div>`;
 }
 function setChartPoint(index){if(!chartData)return;const i=E.clamp(Math.round(index),0,chartData.series.length-1),r=chartData.series[i],dot=document.getElementById('chart-active-dot'),text=document.getElementById('chart-readout'),slider=document.getElementById('history-point');if(dot){dot.setAttribute('cx',chartData.x(i));dot.setAttribute('cy',chartData.y(r.value));}if(text)text.innerHTML=`${esc(r.date)} · <strong>${metricValue(r.value,chartData.unit)}</strong>${r.label?' · '+esc(r.label):''}`;if(slider)slider.value=i;}
 function chartDialog(m){
   if(m.type==='finance-chart'){const metric=H.FINANCE_METRICS[m.id]??H.FINANCE_METRICS.cash,key=H.FINANCE_METRICS[m.id]?m.id:'cash';const series=H.financeSeries(state(),key);return dialogFrame(`${metric[0]} 기록`,'재무 · 은행',`<p class="small muted">${esc(state().financeHistoryInfo?.note??'실제 거래 및 주간 잔액을 기록합니다.')} 같은 주에 거래가 여러 번 있으면 순서대로 표시합니다. 월만 남은 예전 기록은 월 단위로 표시합니다.</p>${chart(series,metric[0],'억 원')}<p class="small muted">${key==='fixed'?'v1.3.0 이후의 월 운영비 기록은 해당 시점의 기본 운영비 0.25억 + 월 이자 + 예상 세금 적립 조정액입니다. 이전 기록은 당시의 운영비와 이자만 보존합니다. 실제 월 결산액은 거래 내역에서 확인합니다.':key==='net'?'제작 중인 영화의 자산가치는 포함하지 않은 현금과 대출의 차이입니다.':key==='gross'?'이전 저장에서 날짜별 극장 매출을 복원할 수 없는 구간은 표시하지 않습니다.':'잔액을 추정해서 늘이거나 과거의 누락된 거래를 만들어 채우지 않습니다.'}</p>`,`${backButton()}${btn('거래 자세히 보기','ledger','','ghost')}`);}
   const f=film(m.id);if(!f)return dialogFrame('흥행 기록','','영화를 찾을 수 없습니다.',backButton());
   const key=m.metric??'audience',title={audience:'주간 관객',gross:'주간 매출',cumulative:'누적 관객'}[key]??'주간 관객';
   const series=H.runSeries(f,key);
   return dialogFrame(`${title} 추이`,esc(f.title),`${chart(series,title,key==='gross'?'억 원':'명')}<p class="small muted">실제 게임 내 집계 값입니다. 이전 월간 기록은 월 단위로 유지되며, 주간 수치와 단순 증감 비교하지 않습니다.</p>`,`${backButton()}${btn('영화 상세','film',`data-id="${f.id}"`,'ghost')}`);
 }
 function ledgerRows(entries){return entries.map(l=>`<div class="ledger-entry"><div>${esc(l.description)}<small>${E.recordDate(l)}</small></div><strong class="${l.amount>0?'lime':''}">${l.amount>0?'+':''}${E.money(l.amount)}</strong></div>`).join('');}
 function ledgerDialog(){const s=state(),all=s.ledger.filter(l=>ui.ledgerFilter==='income'?l.amount>0:ui.ledgerFilter==='expense'?l.amount<0:true),pages=Math.max(1,Math.ceil(all.length/25)),page=E.clamp(ui.ledgerPage??0,0,pages-1);ui.ledgerPage=page;
   return dialogFrame('입출금 자세히 보기',`저장된 거래 ${s.ledger.length}건`, `<div class="toolbar"><label for="ledger-filter">내역</label><select id="ledger-filter" data-field="ledger-filter"><option value="all">전체</option><option value="income" ${ui.ledgerFilter==='income'?'selected':''}>입금</option><option value="expense" ${ui.ledgerFilter==='expense'?'selected':''}>출금</option></select><span class="small muted">25건씩 · 최신순</span></div>${ledgerRows(all.slice(page*25,(page+1)*25))||'<p class="empty">해당 거래가 없습니다.</p>'}${pageControls('ledger-page',page,pages)}<p class="small muted">${esc(s.financeHistoryInfo?.note??'현재 저장에 보존된 거래 내역입니다.')}</p>`,backButton());
 }
 function financePage(){const s=state(),c=E.player(s),limit=E.loanLimit(s),remaining=limit-c.debt;
   const kpis=[['cash','보유 현금',c.cash,'제작·정산 후 실제 잔액'],['receipts','누적 정산',c.totalReceipts,'극장 + OTT · 원작료 차감 후'],['debt','대출 잔액',c.debt,`한도 ${E.money(limit)}`],['fixed','월 운영비 · 세금 포함',T.monthlyCosts(s).total,'기본 운영비 + 이자 + 세금 적립 조정'],['net','현금 − 대출',E.round(c.cash-c.debt),'영화 자산가치 제외'],['ott','OTT 누적 정산',c.totalOttReceipts??0,'OTT 계약 실수령액']];
   return `${pageHead('재무 · 은행','잔액 카드를 누르면 과거부터 현재까지의 기록을 봅니다.')}<div class="finance-kpis">${kpis.map(([id,label,value,note])=>`<button class="stat finance-kpi" data-action="finance-chart" data-id="${id}" aria-label="${label} ${E.money(value)}, 기록 그래프 보기"><span class="stat-label">${label}${icon('chart')}</span><strong class="${value<0?'red':''}">${E.money(value)}</strong><small>${note}</small><span class="stat-link">기록 보기 ${icon('chevron')}</span></button>`).join('')}</div>${c.cash<0?'<div class="notice warning">현재 현금이 부족합니다. 대출 또는 작품 정산으로 자금을 보충해 주세요.</div>':''}<div class="finance-grid"><section class="card compact-bank"><div class="row between"><h2>운영 자금 대출</h2>${icon('bank')}</div><p>월 이자 0.5% · 10억 단위 · 추가 가능 ${E.money(remaining)}</p><div class="amount-grid">${[10,30,50].map(n=>btn(`${n}억<small>대출받기</small>`,'borrow',`data-amount="${n}" ${n>remaining?'disabled':''}`,'ghost')).join('')}</div></section><section class="card compact-bank"><div class="row between"><h2>대출 상환</h2>${icon('check')}</div><p>중도 상환 수수료 없음 · 월 예상 이자 ${E.money(E.round(c.debt*.005))}</p><div class="amount-grid">${[10,50].map(n=>btn(`${n}억<small>원금 상환</small>`,'repay',`data-amount="${n}" ${n>c.cash||n>c.debt?'disabled':''}`,'ghost')).join('')}${btn('전액<small>모두 상환</small>','repay',`data-amount="${c.debt}" ${c.debt<=0||c.cash<c.debt?'disabled':''}`,'ghost')}</div></section></div><section class="card monthly-tax-card"><div class="section-head"><div><h2>월 운영비 · 세금 적립</h2><p class="small muted">매출이 아닌 연간 누적 소득 기준 · 실제 월 납부 제도와 구분</p></div>${btn('계산 내역','tax-details','','ghost small-btn')}</div><p class="small">기본 ${E.money(.25)} + 이자 ${E.money(E.round(c.debt*.005))} + 세금 적립 조정 ${E.money(T.monthlyCosts(s).tax)}</p></section><section class="card recent-ledger"><div class="section-head"><div><h2>최근 입출금</h2><span class="small muted">최근 10건 · 억 원</span></div>${btn('자세히 보기','ledger','','ghost small-btn')}</div>${ledgerRows(s.ledger.slice(0,10))}</section>`;
 }
 function formatOptions(d){
  const formats=C.normalizeFormats(d),effect=C.formatEffect(d),quotes=C.formatCostBreakdown(d,C.formatProductionBase(d),C.FORMATS.map(f=>f.id));
  return `<section class="format-section"><div class="field-label">특수상영 <small>여러 개 선택 가능 · 미선택은 일반 상영</small></div><div class="format-grid">${C.FORMATS.map(f=>{
   const fit=d.genres.some(g=>f.genres.includes(g)),q=quotes.find(q=>q.id===f.id);
   return `<label class="format-option ${formats.includes(f.id)?'selected':''}"><input type="checkbox" data-field="format-toggle" value="${f.id}" ${formats.includes(f.id)?'checked':''}><span><strong>${f.name} <em class="format-cost" data-format-cost="${f.id}">+${E.money(q.cost)}</em></strong><small>${f.description}</small><small>준비 ${E.money(q.setup)} + 작업 ${E.money(q.variable)} · 품질 +${fit?f.quality:.4}</small></span></label>`;
  }).join('')}</div><p class="small muted format-cost-note">현재 ${RT.runtimeOf(d)}분 기준 추가 제작비 <strong>${E.money(effect.cost)}</strong>. 제작 규모·장르 작업량·러닝타임에 따라 달라지며 배우 출연료·원작료에는 가중하지 않습니다. 선택만으로 지출되지 않습니다.</p><details class="format-cost-details"><summary>특수상영 비용 계산 기준</summary><p>기본 준비비 + (촬영·후반 기준비 × 형식별 가중률 × 러닝타임/120 × 장르 작업량). 3D는 22%, 4D는 1.5%, IMAX는 12%, 사운드 특화는 2%를 기본 작업률로 사용합니다.</p><p>공개된 제작 공정을 참고한 게임용 추정 모델이며 업체의 실제 견적표가 아닙니다. IMAX는 대형 화면 대응 촬영과 후반작업을 묶은 기획 옵션입니다. 극장 설비 구입비나 별도 매출 배분은 추가 청구하지 않습니다.</p></details><p class="small muted">현재 장르 기준 기술 품질 +${effect.quality} (합산 최대 +6). 높은 평점이나 흥행이 보장되지는 않습니다. 확정된 영화의 과거 제작비는 바뀌지 않습니다.</p></section>`;
 }

 function teamNotes(d){const s=state(),ids=E.crewIds(d).filter(Boolean),chem=E.teamCompatibility(s,ids),aff=R.teamAffinity(s,ids);return `<details class="fold-section team-chemistry" data-team-panel ${ui.teamOpen?'open':''}><summary>팀 궁합 ${chem} · 친밀도 ${aff} / 100 · 인물 상세 보기</summary><p class="small muted">인물 사진이나 이름을 누르면 기획 내용을 유지한 채 상세정보를 봅니다. 궁합과 친밀도는 별도의 수치입니다.</p><div class="team-person-grid">${ids.map(id=>{const p=person(id),q=E.contractQuote(s,p,ids);return `<article class="team-person-card">${personChip(id)}<div><span>경력 ×${q.historyFactor}</span><span>궁합 ×${q.chemistryFactor}</span></div><div><span>회사 친밀도</span>${relationBadge(id,'c0')}</div><div><span>친밀도 계약 배수</span><b>×${q.relationshipFactor}</b></div></article>`;}).join('')}</div></details>`;}
 function posterArt(f,index=f.poster??0){if(!f)return '';index=Number.isInteger(index)?E.clamp(index,0,11):0;const c=state().companies.find(c=>c.id===f.company),title=String(f.title??'라스트 테이크'),len=Array.from(title).length;
   const genre=f.genres[0],style=['drama','romance','history'].includes(genre)?'literary':['thriller','mystery','sf'].includes(genre)?'suspense':['animation','family','comedy'].includes(genre)?'warm':'epic';
   const size=len>30?7.6:len>20?8.4:len>12?9.6:12.2;
   const tagline={drama:'작은 선택이 남긴, 오래 남을 장면',romance:'다시 마주한 우리, 다음 장면',thriller:'익숙한 풍경 속, 하나의 의문',mystery:'모든 단서는 처음부터 그곳에',comedy:'계획에 없던 하루가 시작된다',sf:'경계 너머에서 만나는 새로운 질문',fantasy:'보이지 않던 세계의 문이 열린다',action:'돌아갈 수 없다면, 앞으로',adventure:'지도가 끝난 곳에서 시작되는 이야기',family:'함께라는 말의 새로운 의미',animation:'작은 용기, 아주 커다란 세계',music:'서로 다른 소리가 하나의 장면으로',history:'시간이 지나도 지워지지 않는 선택'}[genre]??'한 편의 이야기가 당신을 기다립니다';
   return `<div class="movie-poster poster-v12 ${style} composition-${index%3}" style="background-position:${index%4*100/3}% ${Math.floor(index/4)*50}%;--poster-title:${size}cqw" role="img" aria-label="${esc(title)} 영화 포스터"><div class="poster-content"><small class="poster-present">${esc(c?.name??'LAST TAKE')} PRESENTS</small><p class="poster-tagline">${tagline}</p><div class="poster-type"><span class="poster-genres">${f.genres.map(g=>GENRE[g].name).join(' · ')}</span><strong class="poster-title">${esc(title)}</strong><span class="poster-rule"></span><small class="poster-billing">${f.director?esc(person(f.director)?.name??'')+' 감독':''}${f.leads.length?' · '+f.leads.map(id=>esc(person(id)?.name??'')).join('  '):''}</small><small class="poster-date">${f.status==='streaming'?'AN OTT ORIGINAL':f.releaseMonth!=null?E.date(f.releaseMonth)+' 개봉':'COMING SOON'}</small></div></div></div>`;
 }
 function brandLogo(p){const shapes={tiles:'<path d="M8 8h12v12H8zm16 0h12v12H24zM8 24h12v12H8zm16 0h12v12H24z"/>',orbit:'<ellipse cx="22" cy="23" rx="16" ry="9" fill="none" stroke="currentColor" stroke-width="2.5" transform="rotate(-25 22 23)"/><path d="m18 13 13 10-13 10z"/>',waves:'<path d="M5 15q8-10 17 0t17 0M5 23q8-10 17 0t17 0M5 31q8-10 17 0t17 0" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"/>',screen:'<rect x="5" y="9" width="34" height="25" rx="8" fill="none" stroke="currentColor" stroke-width="3"/><path d="m18 16 11 6-11 6z"/>',cushion:'<path d="M8 9q14-8 28 0 8 13 0 26-14 8-28 0-8-13 0-26z" fill="none" stroke="currentColor" stroke-width="3"/><path d="m18 15 12 7-12 7z"/>'};return `<span class="ott-brand" style="--ott:${p.color}" role="img" aria-label="가상 OTT ${p.name} 로고"><svg viewBox="0 0 44 44" fill="currentColor" aria-hidden="true">${shapes[p.shape]}</svg><span><strong>${p.wordmark}</strong><small>${p.name}</small></span></span>`;}
 function ottFilmCard(f){const p=C.OTT_PLATFORMS.find(p=>p.id===f.ott?.platform);return `<article class="card ott-film-card"><button class="ott-poster-link" data-action="film" data-id="${f.id}" aria-label="${esc(f.title)} 상세">${posterArt(f)}</button><div>${p?brandLogo(p):''}<h3><button class="film-link" data-action="film" data-id="${f.id}">${esc(f.title)}</button></h3><p class="small muted">${f.ott?E.weekDate(f.ott.startWeek)+' 독점 공개':''}</p><div class="rating-pair">${scoreButton(f,'critic',true)}${scoreButton(f,'audience',true)}</div>${!f.ott?.availableReviews?'<p class="small muted">1주 뒤 시청자 평 도착</p>':''}</div></article>`;}
 function ottPage(){const s=state(),all=s.films.filter(f=>f.status==='streaming').slice().reverse(),ready=E.myFilms(s).filter(f=>['ready','shelved'].includes(f.status)),size=8,pages=Math.max(1,Math.ceil(all.length/size)),page=E.clamp(ui.ottPage??0,0,pages-1);ui.ottPage=page;
   return `${pageHead('OTT 상영관','극장이 아닌, 또 하나의 첫 공개. 평론가와 시청자의 반응을 모았습니다.')}<div class="ott-platform-strip">${C.OTT_PLATFORMS.map(brandLogo).join('')}</div><p class="small muted">모두 실존 서비스에서 착안한 가상의 패러디 브랜드입니다. 실제 업체와 관련이 없으며 로고는 게임용 독자 도형입니다.</p>${ready.length?`<details class="fold-section"><summary>OTT 제안을 받을 수 있는 완성작 · ${ready.length}편</summary><div class="stack">${ready.map(f=>`<div class="ott-ready-row"><strong>${esc(f.title)}</strong>${btn('5곳의 제안 보기','ott-offers',`data-id="${f.id}" ${f.activePromotion?'disabled':''}`,'ghost small-btn')}</div>`).join('')}</div></details>`:''}<div class="section-head mt"><h2>OTT 공개작 <span class="count">${all.length}편</span></h2></div>${all.length?`<div class="ott-film-grid">${all.slice(page*size,(page+1)*size).map(ottFilmCard).join('')}</div>${pages>1?pageControls('ott-page',page,pages):''}`:`<div class="card empty"><h3>아직 OTT 공개작이 없습니다.</h3><p>완성된 영화 상세에서 ‘OTT 제안 보기’를 선택하세요.<br>독점 계약금은 즉시 정산되고, 시청자 평은 공개 1주 후 도착합니다.</p></div>`}`;
 }
 function producerOTTNet(f,offer){return E.round(offer.net-E.round(offer.net*(f.investment?.share??0)));}
 function ottOffersDialog(f){if(!f)return dialogFrame('OTT 제안','','작품이 없습니다.',backButton());const offers=C.ottOffers(f),selected=offers.find(o=>o.platform===ui.ottSelected);return dialogFrame('OTT 독점 공개 제안',esc(f.title),`<div class="notice"><p>극장에 개봉하지 않고 OTT 한 곳에 독점 제공합니다. 원작료와 공동제작 투자사 몫을 차감한 실수령을 표시합니다. 계약금은 즉시 정산하며, 계약 후 극장 개봉·다른 OTT 재판매는 불가합니다.</p></div><div class="ott-offer-grid" role="radiogroup" aria-label="OTT사 한 곳 선택">${offers.map(o=>{const p=C.OTT_PLATFORMS.find(p=>p.id===o.platform);return `<button class="ott-offer ${ui.ottSelected===p.id?'selected':''}" data-action="select-ott" data-id="${p.id}" role="radio" aria-checked="${ui.ottSelected===p.id}">${brandLogo(p)}<small>${p.tag}</small><strong class="ott-offer-amount">${E.money(o.amount)}</strong><span>${o.reason}</span><small>원작료 ${E.money(o.royalty)}${f.investment?` · 투자사 ${Math.round(f.investment.share*100)}%`:""} · 실수령 ${E.money(producerOTTNet(f,o))}</small></button>`;}).join('')}</div><p class="small muted">게임 내 가상 제안입니다. 최초 제작 규모·작품 품질·장르·예상 시청 취향과 플랫폼 선호를 반영합니다. 창을 다시 열어도 제안이 임의로 바뀌지 않습니다.</p>`,`${backButton()}${btn(selected?`실수령 ${E.money(producerOTTNet(f,selected))} · 계약 확인`:'OTT사를 선택하세요','ott-confirm',`data-id="${f.id}" ${!selected?'disabled':''}`,'primary')}`);}
 function ottConfirmDialog(f){const p=C.OTT_PLATFORMS.find(p=>p.id===ui.ottSelected),o=f&&C.ottOffers(f).find(x=>x.platform===p?.id);if(!o)return dialogFrame('OTT 계약 확인','','플랫폼을 다시 선택해 주세요.',backButton());return dialogFrame('독점 공개 계약을 확정할까요?',esc(f.title),`${brandLogo(p)}<div class="detail-metrics"><div><small>계약금</small><strong>${E.money(o.amount)}</strong></div><div><small>원작료</small><strong>${E.money(o.royalty)}</strong></div><div><small>제작사 실수령</small><strong>${E.money(producerOTTNet(f,o))}</strong></div><div><small>작품 손익</small><strong>${E.money(producerOTTNet(f,o)+(f.receipts??0)+(f.investment?.amount??0)-f.spent)}</strong></div></div><div class="notice warning"><p>확정하면 극장 미개봉 OTT 독점 공개작으로 전환됩니다. 극장 관객·매출은 발생하지 않고, 동일 영화의 재판매는 불가합니다. 선택만으로 비용이나 수입은 발생하지 않습니다.</p></div>`,`${backButton()}${btn('독점 공개 · 계약금 받기','ott-sign',`data-id="${f.id}"`,'primary')}`);}
 function companyDialog(c){if(!c)return dialogFrame('제작사 정보','','제작사를 찾을 수 없습니다.',backButton());const works=state().films.filter(f=>f.company===c.id);return dialogFrame('제작사 상세',esc(c.name),`<div class="company-profile"><span class="company-symbol">${X.LOGOS[c.logo??0]}</span><div><h3>${esc(c.name)}</h3><p>${GENRE[c.genre]?.name??''} · ${c.id==='c0'?'우리 제작사':'경쟁 제작사'}</p></div></div><div class="detail-metrics"><div><small>누적 관객</small><strong>${E.viewers(c.totalAudience)}명</strong></div><div><small>총 정산</small><strong>${E.money(c.totalReceipts)}</strong></div><div><small>참여 영화</small><strong>${works.length}편</strong></div><div><small>수상</small><strong>${c.trophies}개</strong></div></div><h3>작품 목록</h3><div class="company-works">${works.slice().reverse().map(f=>`<button data-action="film-peek" data-id="${f.id}">${posterArt(f)}<span><strong>${esc(f.title)}</strong><small>${ctx.statusLabel(f)} · ${f.status==='streaming'?'OTT 공개작':E.viewers(f.audience)+'명'}</small></span>${icon('chevron')}</button>`).join('')||'<p class="small muted">아직 제작한 영화가 없습니다.</p>'}</div>`,backButton());}
 function filmDialog(f){if(!f)return dialogFrame('영화 정보','','영화를 찾을 수 없습니다.');const s=state(),c=s.companies.find(c=>c.id===f.company),own=f.company==='c0',ready=['ready','shelved'].includes(f.status),ott=f.status==='streaming',completed=!['production','reshoot'].includes(f.status),tab=ui.filmTab??'overview';
   const tabs=`<div class="tabbar dialog-tabs">${[['overview','작품 · 성과'],['crew','제작진'],['history','제작 기록']].map(([key,label])=>`<button data-action="film-tab" data-id="${key}" class="${tab===key?'active':''}">${label}</button>`).join('')}</div>`;
   let body='';
   if(tab==='overview'){
    const plot=completed?C.ensurePlot(f):f.script.synopsis,paragraphs=plot.split('\n\n');
    body=`<div class="film-top-credits">${companyChip(c)}${personChip(f.director,'감독')}${f.leads.map(id=>personChip(id,'주연')).join('')}</div><div class="film-overview v12-film-overview"><div class="film-overview-poster">${posterArt(f)}</div><div><div class="row wrap">${tags(f.genres)}<span class="tag outline">${ctx.statusLabel(f)}</span></div><h3 class="detail-title">${esc(f.title)}</h3><div class="format-badges"><span>${RT.runtimeOf(f)}분 · 하루 ${RT.dailyShows(f)}회 모형</span>${f.runtimeLegacy?'<span>이전 저장 기본 길이</span>':''}${C.normalizeFormats(f).map(id=>`<span>${C.FORMATS.find(x=>x.id===id).name}</span>`).join('')||'<span>일반 상영</span>'}</div><div class="rating-pair film-rating-pair">${scoreButton(f,'critic')}${scoreButton(f,'audience')}</div><h4 class="plot-label">${completed?'줄거리':'기획 시놉시스'}</h4><p class="plot-excerpt">${esc(paragraphs[0])}${completed?' '+esc(paragraphs[1]??''):''}</p>${completed?`<details class="plot-details"><summary>전체 줄거리 보기 · 결말 포함</summary>${paragraphs.slice(1).map(p=>`<p>${esc(p)}</p>`).join('')}</details>`:''}</div></div>${ott?`<div class="ott-contract-summary">${brandLogo(C.OTT_PLATFORMS.find(p=>p.id===f.ott.platform))}<p>${E.weekDate(f.ott.startWeek)} 독점 공개 · 극장 미개봉</p></div>`:''}<div class="detail-metrics film-financials"><div><small>총 제작비</small><strong>${E.money(f.spent)}</strong></div><div><small>${ott?'OTT 계약금':'누적 관객'}</small><strong>${ott?E.money(f.ott.amount):E.viewers(f.audience)+'명'}</strong></div><div><small>제작사 정산</small><strong>${E.money(f.receipts)}</strong></div><div><small>${ott?'확정 작품 손익':'현재 작품 손익'}</small><strong class="${E.filmProfit(f)<0?'red':''}">${E.money(E.filmProfit(f))}</strong></div></div>${f.runs.length?`<div class="row wrap graph-shortcuts">${btn(`${icon('chart')} 주간 관객`,'film-chart',`data-id="${f.id}" data-key="audience"`,'ghost small-btn')}${btn(`${icon('chart')} 주간 매출`,'film-chart',`data-id="${f.id}" data-key="gross"`,'ghost small-btn')}${btn(`${icon('chart')} 누적 관객`,'film-chart',`data-id="${f.id}" data-key="cumulative"`,'ghost small-btn')}</div>`:''}${own&&ready?`<div class="notice small"><p>${f.activePromotion?'진행 중인 홍보가 끝나면 극장 개봉 또는 OTT 계약이 가능합니다.':'극장 개봉 · 창고 보관 · OTT 독점 공개 중 선택할 수 있습니다.'}</p></div>`:''}`;
   }
   if(tab==='crew')body=`<div class="film-crew-grid">${E.credits(f).map(id=>{const p=person(id)??f.castSnapshot?.[id];return `<article class="crew-info-tile">${personChip(id)}<small>계약 ${E.money(f.contracts?.[id]?.paid??0)}</small></article>`;}).join('')}</div>${teamNotes(f)}${filmCareerNotes(f)}<details class="fold-section"><summary>섭외 협상 기록</summary>${(f.negotiations??[]).map(r=>`<p class="small">${esc(person(r.person)?.name)} · ${esc(r.message)}</p>`).join('')||'<p class="small muted">이전 버전 계약 기록입니다.</p>'}</details>`;
   if(tab==='history')body=`${timelinePanel(f)}<details class="fold-section"><summary>현장 결정 기록 · ${f.decisions.length}건</summary>${f.decisions.map(d=>`<p class="small record-line">${esc(EVENTS[d.event]?.[0]??'현장 결정')} · ${esc(EVENTS[d.event]?.[2]?.[d.index]?.[0]??d.text??'결정 완료')}</p>`).join('')||'<p class="small muted">아직 결정 기록이 없습니다.</p>'}</details>${ott?`<div class="relationship-row"><strong>OTT 공개</strong><span>${E.weekDate(f.ott.startWeek)}</span></div>`:''}<details class="fold-section"><summary>특수상영 제작 내역</summary><p>${C.normalizeFormats(f).map(id=>C.FORMATS.find(x=>x.id===id).name).join(' · ')||'일반 상영'} · 추가 기술 제작비 ${E.money(f.presentationBudget??0)} · 기술 품질 +${f.formatQuality??0}</p></details><details class="fold-section"><summary>추가 계약 · 홍보 기록</summary>${(f.businessHistory??[]).slice().reverse().map(r=>`<p class="small record-line">${E.recordDate(r)} · ${esc(r.text)}</p>`).join('')||'<p class="small muted">아직 기록이 없습니다.</p>'}</details>`;
   const actions=own?`${RT.editingAvailable(f)||f.pendingEdit?btn('후반 편집','runtime-edit',`data-id="${f.id}"`,'ghost'):''}${f.pending!=null?btn('현장 결정','event',`data-id="${f.id}"`,'primary'):''}${['production','reshoot','ready','shelved'].includes(f.status)?btn('제작·홍보','business',`data-id="${f.id}"`,'ghost'):''}${ready?`${btn('극장 개봉','release',`data-id="${f.id}" ${E.releaseWaitWeeks(s)||f.activePromotion?'disabled':''}`,'primary')}${btn('OTT 제안 보기','ott-offers',`data-id="${f.id}" ${f.activePromotion?'disabled':''}`,'ghost')}${btn(f.status==='shelved'?'꺼내기':'창고 보관',f.status==='shelved'?'unshelve':'shelve',`data-id="${f.id}"`,'ghost')}${!f.extended&&f.status==='ready'?btn('추가 제작','extend-confirm',`data-id="${f.id}"`,'ghost'):''}`:''}${f.status==='closed'?btn('속편 기획','sequel',`data-id="${f.id}"`,'primary'):''}${ott?btn('OTT 상영관','nav','data-view="ott"','primary'):''}`:'';
   return dialogFrame(`<span class="film-heading"><span class="film-heading-poster">${posterArt(f)}</span><span class="film-heading-copy"><small>영화 상세</small><span>${esc(f.title)}</span></span></span>`,esc(c.name),tabs+(ctx.growth?.()?.filmTools(f)??'')+body,`<div class="row wrap film-actions">${actions}${ui.peekStack?.length?backButton():btn('닫기','close','','ghost')}</div>`);
 }
 function modalMarkup(m){if(m.type==='critic-reviews')return reviewsDialog(film(m.id),'critic');if(m.type==='audience-reviews')return reviewsDialog(film(m.id),'audience');if(m.type==='finance-chart'||m.type==='film-chart')return chartDialog(m);if(m.type==='ledger')return ledgerDialog();if(m.type==='company-info')return companyDialog(state().companies.find(c=>c.id===m.id));if(m.type==='ott-offers')return ottOffersDialog(film(m.id));if(m.type==='ott-confirm')return ottConfirmDialog(film(m.id));return '';}
 function handleField(e){const t=e.target;
  if(t.dataset.field==='chart-point'){setChartPoint(Number(t.value));return true;}
  if(t.dataset.field==='format-toggle'){const d=ui.draft;if(!d)return true;const current=C.normalizeFormats(d);d.formats=t.checked?[...new Set([...current,t.value])]:current.filter(x=>x!==t.value);renderDialog();return true;}
  if(t.dataset.field==='ledger-filter'){ui.ledgerFilter=t.value;ui.ledgerPage=0;renderDialog();return true;}
  return false;
 }
 function handleAction(a,id,button){
  if(a==='feature-back'||a==='close'&&ui.peekStack?.length){back();return true;}
  if(a==='nav'||a==='home'||a==='reset'){ui.peekStack=[];return false;}
  if(a==='person-peek'||a==='person'&&ui.modal){deepOpen('person',id);return true;}
  if(a==='film-peek'||a==='film'&&ui.modal){
   if(ui.modal?.type==='film'&&ui.modal.id===id)return true;
   if(['business','extend-confirm'].includes(ui.modal?.type)&&ui.peekStack?.at(-1)?.modal?.type==='film'&&ui.peekStack.at(-1).modal.id===id)back();else deepOpen('film',id);
   return true;
  }
  if(a==='business'&&ui.modal){deepOpen('business',id);return true;}
  if(a==='company-info'){deepOpen(a,id);return true;}
  if(a==='critic-reviews'||a==='audience-reviews'){deepOpen(a,id);return true;}
  if(a==='finance-chart'){deepOpen(a,id);return true;}
  if(a==='film-chart'){deepOpen(a,id,{metric:button.dataset.key??'audience'});return true;}
  if(a==='ledger'){ui.ledgerPage=0;ui.ledgerFilter='all';deepOpen('ledger');return true;}
  if(a==='review-page'){ui.reviewPage=(ui.reviewPage??0)+Number(button.dataset.delta);renderDialog();return true;}
  if(a==='ledger-page'){ui.ledgerPage=(ui.ledgerPage??0)+Number(button.dataset.delta);renderDialog();return true;}
  if(a==='box-page'){ui.boxPage=(ui.boxPage??0)+Number(button.dataset.delta);render();return true;}
  if(a==='ott-page'){ui.ottPage=(ui.ottPage??0)+Number(button.dataset.delta);render();return true;}
  if(a==='ott-offers'){ui.ottSelected=null;deepOpen(a,id);return true;}
  if(a==='select-ott'){ui.ottSelected=ui.ottSelected===id?null:id;renderDialog();return true;}
  if(a==='ott-confirm'){deepOpen(a,id);return true;}
  if(a==='ott-sign'){mutate(()=>{E.sellToOTT(state(),id,ui.ottSelected);ui.modal=null;ui.peekStack=[];ui.view='ott';},'OTT 독점 계약금이 정산되었습니다.');return true;}
  if(a==='notification-open'){const n=state().notifications.find(n=>n.id===Number(id));if(n?.personId){deepOpen('person',n.personId);return true;}}
  return false;
 }
 document.addEventListener('toggle',event=>{if(event.target.matches?.('details[data-team-panel]')&&event.target.isConnected)ui.teamOpen=event.target.open;},true);
 document.addEventListener('pointermove',event=>{const svg=event.target.closest?.('[data-feature-chart]');if(!svg||!chartData)return;const rect=svg.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width*680,index=(x-70)/(680-70-20)*(chartData.series.length-1);setChartPoint(index);},{passive:true});
 return {boxofficeTable,financePage,filmDialog,teamNotes,posterArt,formatOptions,ottPage,ottFilmCard,brandLogo,scoreButton,modalMarkup,handleField,handleAction,back,deepOpen};
}
